require_once __DIR__.'/../includes/auth.php';require_guest();$selector=(string)($_POST['selector']??$_GET['selector']??'');$token=(string)($_POST['token']??$_GET['token']??'');$record=find_valid_auth_token('password_reset',$selector,$token);$error='';
