    if(!$record)$error='This reset link is invalid or expired.';elseif(strlen($password)<12||strlen($password)>200)$error='Password must be between 12 and 200 characters.';elseif($password!==$confirm)$error='Passwords do not match.';else{$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('UPDATE users SET password_hash=?,session_version=session_version+1 WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),(int)$record['user_id']]);$pdo->prepare('UPDATE auth_tokens SET used_at=NOW() WHERE id=? AND used_at IS NULL')->execute([(int)$record['id']]);$pdo->prepare("DELETE FROM auth_tokens WHERE user_id=? AND purpose='password_reset' AND used_at IS NULL")->execute([(int)$record['user_id']]);$pdo->commit();log_activity((int)$record['user_id'],'password_reset_completed','user',(int)$record['user_id']);flash('success','Password updated. You can now login.');redirect('auth/login.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not reset the password. Please request a new link.';}}
